SELECT *
FROM ai_context_change_suggestions
WHERE suggestion_id = #{suggestionId}
  AND user_id       = #{userId}

SELECT *
FROM ai_context_change_suggestions
WHERE suggestion_id = #{suggestionId}
  AND user_id       = #{userId}
FOR UPDATE

SELECT *
FROM ai_context_change_suggestions
WHERE conversation_id = #{conversationId}
  AND user_id         = #{userId}
  AND status           = 'PROPOSED'
ORDER BY suggestion_id ASC

SELECT *
FROM ai_context_change_suggestions
WHERE source_message_id = #{sourceMessageId}
  AND user_id           = #{userId}
ORDER BY suggestion_id ASC

mapper.update:
UPDATE ai_context_change_suggestions
SET status              = 'APPLIED',
    resolved_at         = #{resolvedAt},
    resulting_context_id = #{resultingContextId}
WHERE suggestion_id = #{suggestionId}
  AND user_id       = #{userId}
  AND status        = 'PROPOSED'

UPDATE ai_context_change_suggestions
SET status      = 'DISMISSED',
    resolved_at = #{resolvedAt}
WHERE suggestion_id = #{suggestionId}
  AND user_id       = #{userId}
  AND status        = 'PROPOSED'
